const body = $json.body ?? {};

const date = body.date;
const durationMinutes = body.durationMinutes;

// --------------------------------------------------
// 1. DATE REQUIRED
// --------------------------------------------------

if (!date) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: "MISSING_DATE",
          message: "Date is required.",
          field: "date"
        }
      }
    }
  ];
}

// --------------------------------------------------
// 2. DATE FORMAT
// --------------------------------------------------

const datePattern = /^\d{4}-\d{2}-\d{2}$/;

if (!datePattern.test(date)) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: "INVALID_DATE_FORMAT",
          message: "Date must be in YYYY-MM-DD format.",
          field: "date",
          received: date
        }
      }
    }
  ];
}

// --------------------------------------------------
// 3. REAL CALENDAR DATE
// --------------------------------------------------

const [year, month, day] = date.split("-").map(Number);

const parsedDate = new Date(
  Date.UTC(year, month - 1, day)
);

const isRealDate =
  parsedDate.getUTCFullYear() === year &&
  parsedDate.getUTCMonth() === month - 1 &&
  parsedDate.getUTCDate() === day;

if (!isRealDate) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        error: {
          code: "INVALID_DATE",
          message: "The supplied date does not exist.",
          field: "date",
          received: date
        }
      }
    }
  ];
}

// --------------------------------------------------
// 4. DURATION VALIDATION
// --------------------------------------------------

let requestedDuration = null;

if (
  durationMinutes !== undefined &&
  durationMinutes !== null &&
  durationMinutes !== ""
) {
  requestedDuration = Number(durationMinutes);

  if (!Number.isInteger(requestedDuration)) {
    return [
      {
        json: {
          valid: false,
          statusCode: 400,
          error: {
            code: "INVALID_DURATION",
            message: "durationMinutes must be an integer.",
            field: "durationMinutes",
            received: durationMinutes
          }
        }
      }
    ];
  }

  if (
    ![15, 30, 45, 60, 90, 120].includes(
      requestedDuration
    )
  ) {
    return [
      {
        json: {
          valid: false,
          statusCode: 400,
          error: {
            code: "UNSUPPORTED_DURATION",
            message: "Unsupported appointment duration.",
            field: "durationMinutes",
            received: requestedDuration,
            allowed: [15, 30, 45, 60, 90, 120]
          }
        }
      }
    ];
  }
}

// --------------------------------------------------
// 5. VALID REQUEST
// --------------------------------------------------

return [
  {
    json: {
      valid: true,
      statusCode: 200,
      date,
      requestedDuration
    }
  }
];

const date = $json.date;
const requestedDuration = $json.requestedDuration;

// --------------------------------------------------
// BUSINESS CONFIGURATION
// --------------------------------------------------

const config = {
  timezone: "Asia/Karachi",

  defaultAppointmentDurationMinutes: 60,

  allowedDurations: [
    15,
    30,
    45,
    60,
    90,
    120
  ],

  bufferMinutes: 15,

  workingHours: {
    monday: [
      {
        start: "09:00",
        end: "17:00"
      }
    ],

    tuesday: [
      {
        start: "09:00",
        end: "17:00"
      }
    ],

    wednesday: [
      {
        start: "09:00",
        end: "17:00"
      }
    ],

    thursday: [
      {
        start: "09:00",
        end: "17:00"
      }
    ],

    friday: [
      {
        start: "09:00",
        end: "17:00"
      }
    ],

    saturday: [],

    sunday: []
  }
};

// --------------------------------------------------
// DETERMINE APPOINTMENT DURATION
// --------------------------------------------------

const appointmentDurationMinutes =
  requestedDuration ??
  config.defaultAppointmentDurationMinutes;

// --------------------------------------------------
// RETURN CONFIGURATION
// --------------------------------------------------

return [
  {
    json: {
      date,
      appointmentDurationMinutes,
      config
    }
  }
];

const {
  date,
  config,
  appointmentDurationMinutes
} = $json;

// --------------------------------------------------
// DETERMINE DAY OF WEEK
// --------------------------------------------------

const requestedDate = new Date(
  `${date}T00:00:00`
);

const dayNames = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday"
];

const dayName =
  dayNames[requestedDate.getDay()];

// --------------------------------------------------
// GET WORKING PERIODS
// --------------------------------------------------

const workingPeriods =
  config.workingHours[dayName] || [];

// --------------------------------------------------
// BUSINESS CLOSED
// --------------------------------------------------

if (workingPeriods.length === 0) {
  return [
    {
      json: {
        date,
        timezone: config.timezone,
        appointmentDurationMinutes,
        day: dayName,
        workingPeriods: [],
        slots: []
      }
    }
  ];
}

// --------------------------------------------------
// GENERATE SLOTS
// --------------------------------------------------

const duration =
  appointmentDurationMinutes;

const slots = [];

for (const period of workingPeriods) {

  const [startHour, startMinute] =
    period.start.split(":").map(Number);

  const [endHour, endMinute] =
    period.end.split(":").map(Number);

  let currentMinutes =
    startHour * 60 + startMinute;

  const endMinutes =
    endHour * 60 + endMinute;

  while (
    currentMinutes + duration <=
    endMinutes
  ) {

    // ----------------------------------------------
    // SLOT START
    // ----------------------------------------------

    const hour =
      Math.floor(currentMinutes / 60);

    const minute =
      currentMinutes % 60;

    const start =
      `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;

    // ----------------------------------------------
    // SLOT END
    // ----------------------------------------------

    const endTotalMinutes =
      currentMinutes + duration;

    const endHourValue =
      Math.floor(endTotalMinutes / 60);

    const endMinuteValue =
      endTotalMinutes % 60;

    const end =
      `${String(endHourValue).padStart(2, "0")}:${String(endMinuteValue).padStart(2, "0")}`;

    // ----------------------------------------------
    // SLOT
    // ----------------------------------------------

    slots.push({
      start,
      end,

      startDateTime:
        `${date}T${start}:00+05:00`,

      endDateTime:
        `${date}T${end}:00+05:00`
    });

    // Move to next slot
    currentMinutes += duration;
  }
}

// --------------------------------------------------
// RETURN GENERATED SLOTS
// --------------------------------------------------

return [
  {
    json: {
      date,
      timezone: config.timezone,
      appointmentDurationMinutes:
        duration,
      day: dayName,
      workingPeriods,
      slots
    }
  }
];

const generatedSlots =
  $("Generate Appointment Slots")
    .first()
    .json;

const slots =
  generatedSlots.slots || [];

const events =
  $input.all();

const bookedSlots = [];

// --------------------------------------------------
// COLLECT BOOKED CALENDAR EVENTS
// --------------------------------------------------

for (const eventItem of events) {

  const event =
    eventItem.json;

  // Ignore events without
  // proper start/end datetime
  if (
    !event.start?.dateTime ||
    !event.end?.dateTime
  ) {
    continue;
  }

  bookedSlots.push({
    start: new Date(
      event.start.dateTime
    ),

    end: new Date(
      event.end.dateTime
    )
  });
}

// --------------------------------------------------
// REMOVE OVERLAPPING SLOTS
// --------------------------------------------------

const availableSlots =
  slots.filter((slot) => {

    const slotStart =
      new Date(
        `${generatedSlots.date}T${slot.start}:00+05:00`
      );

    const slotEnd =
      new Date(
        `${generatedSlots.date}T${slot.end}:00+05:00`
      );

    const overlaps =
      bookedSlots.some((event) => {

        return (
          event.start < slotEnd &&
          event.end > slotStart
        );

      });

    return !overlaps;
  });

// --------------------------------------------------
// RETURN AVAILABILITY DATA
// --------------------------------------------------

return [
  {
    json: {

      date:
        generatedSlots.date,

      timezone:
        generatedSlots.timezone,

      appointmentDurationMinutes:
        generatedSlots.appointmentDurationMinutes,

      day:
        generatedSlots.day,

      workingPeriods:
        generatedSlots.workingPeriods,

      availableSlots,

      bookedEventCount:
        bookedSlots.length
    }
  }
];

const {
  date,
  timezone,
  appointmentDurationMinutes,
  day,
  workingPeriods,
  availableSlots,
  bookedEventCount
} = $json;

// --------------------------------------------------
// DETERMINE AVAILABILITY
// --------------------------------------------------

const slotCount =
  availableSlots.length;

const available =
  slotCount > 0;

// --------------------------------------------------
// DETERMINE REASON
// --------------------------------------------------

let reason = null;

if (!available) {

  if (workingPeriods.length === 0) {

    reason = "BUSINESS_CLOSED";

  } else {

    reason = "FULLY_BOOKED";

  }
}

// --------------------------------------------------
// BUILD API RESPONSE
// --------------------------------------------------

return [
  {
    json: {

      success: true,

      date,

      timezone,

      day,

      available,

      reason,

      appointmentDurationMinutes,

      slots: availableSlots,

      meta: {

        bookedEventCount,

        slotCount

      }
    }
  }
];
